database.schema_and_seed_sql:
PRAGMA foreign_keys=ON;
CREATE TABLE sites(site_id INTEGER PRIMARY KEY,site_name TEXT NOT NULL,region TEXT NOT NULL);
CREATE TABLE devices(device_id INTEGER PRIMARY KEY,site_id INTEGER NOT NULL REFERENCES sites(site_id),device_name TEXT NOT NULL,category TEXT NOT NULL,installed_on TEXT NOT NULL);
CREATE TABLE tickets(ticket_id INTEGER PRIMARY KEY,device_id INTEGER NOT NULL REFERENCES devices(device_id),opened_at TEXT NOT NULL,closed_at TEXT,priority TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE labor_entries(entry_id INTEGER PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(ticket_id),technician TEXT NOT NULL,minutes INTEGER NOT NULL,billable INTEGER NOT NULL);
CREATE TABLE parts_used(line_id INTEGER PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(ticket_id),part_name TEXT NOT NULL,quantity INTEGER NOT NULL,unit_cost_cny REAL NOT NULL);
CREATE TABLE invoices(invoice_id INTEGER PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(ticket_id),issued_on TEXT NOT NULL,amount_cny REAL NOT NULL);
CREATE TABLE receipts(receipt_id INTEGER PRIMARY KEY,invoice_id INTEGER NOT NULL REFERENCES invoices(invoice_id),paid_on TEXT NOT NULL,amount_cny REAL NOT NULL);
